import{_ as t,o,c as s,a5 as a}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"自动解包","description":"在 Vue 的模板里， 只有作为“顶层”绑定的 Ref 会被自动解包 。具体来说： 1. ref() vs reactive() const x ref(1)：x 是一个含有 .value 的对象，Vue 会在模板里把 x 当成原始值 1 来渲染。 const state rea。","frontmatter":{"title":"自动解包","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在 Vue 的模板里， 只有作为“顶层”绑定的 Ref 会被自动解包 。具体来说： 1. ref() vs reactive() const x ref(1)：x 是一个含有 .value 的对象，Vue 会在模板里把 x 当成原始值 1 来渲染。 const state rea。","sidebarWeight":66,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/template/自动解包.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/自动解包.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/自动解包.md"}'),r={name:"posts/Vue系统教程/02-模板、组件与交互/自动解包.md"};function l(u,e,n,i,c,f){return o(),s("div",null,[...e[0]||(e[0]=[a('<div><h1 id="自动解包" tabindex="-1">自动解包 <a class="header-anchor" href="#自动解包" aria-label="Permalink to &quot;自动解包&quot;">​</a></h1><blockquote><p>本节目标：理解“自动解包”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 的模板里，<strong>只有作为“顶层”绑定的 Ref 会被自动解包</strong>。具体来说：</p></blockquote><ol><li><strong>ref() vs reactive()</strong><ul><li>const x = ref(1)：x 是一个含有 .value 的对象，Vue 会在模板里把 x 当成原始值 1 来渲染。</li><li>const state = reactive({ foo: ref(1) })：此时 state.foo 本身是一个 Ref，但它被包在一个 Reactive 对象里。Vue 在模板里读取 state.foo，只认为它是个普通属性，<strong>不会</strong>继续去拿它的 .value。</li></ul></li><li><strong>自动解包规则</strong><ul><li><strong>顶层变量</strong>：你在 &lt;script setup&gt; 里写了 const count = ref(0)，模板里写 {{ count }} 或 :value=&quot;count&quot;，Vue 会自动渲染成 0。</li><li><strong>嵌套属性</strong>：如果你写 :value=&quot;state.count&quot;，哪怕 state.count 是个 Ref，也会渲染成 [object Object]，因为 Vue 只做了一层“取属性”，没再去取那一层的 .value。</li></ul></li><li><strong>为什么用 toRefs 解决</strong>****当你对 state 做 const { formattedValue } = toRefs(state)，就把 state.formattedValue 这个 Ref <strong>提升</strong>成了一个“顶层变量” formattedValue。模板里 :value=&quot;formattedValue&quot;，这次就符合自动解包规则，Vue 会展示 formattedValue.value 的内容，而不是整个 Ref 对象。</li></ol><p><strong>总结</strong>：</p><ul><li><strong>自动解包只针对顶层响应式引用</strong>，不会递归地把 Reactive 对象里的 Ref 给拆开。</li><li>如果你想让嵌套在 Reactive 对象里的某个 Ref 在模板中也自动解包，就必须把它“拆”到顶层，最常用的做法就是 toRefs(state)。</li></ul></div>',1)])])}const _=t(r,[["render",l]]);export{g as __pageData,_ as default};
